<main class="admin-shell"><?= view('partials/admin_sidebar',['active'=>'payments']) ?><section class="admin-content"><div class="admin-topbar"><div><span class="eyebrow accent">FINANCE</span><h1 data-testid="payments-page-title">Payments</h1><p>Only payment and reconciliation data appears on this page.</p></div></div><?= view('partials/flash') ?><form class="admin-panel report-filters" method="get" action="<?= base_url('admin/payments') ?>" data-testid="payment-filter-form"><label>Event<select name="event_id" data-testid="payment-event-filter"><option value="0">All events</option><?php foreach($events as $event): ?><option value="<?= $event['id'] ?>" <?= (int)$filters['event_id']===(int)$event['id']?'selected':'' ?>><?= esc($event['name']) ?></option><?php endforeach ?></select></label><label>Status<select name="status" data-testid="payment-status-filter"><option value="">All statuses</option><?php foreach(['created','pending','initiated','success','failed','cancelled','refunded','unknown'] as $status): ?><option value="<?= $status ?>" <?= $filters['status']===$status?'selected':'' ?>><?= strtoupper($status) ?></option><?php endforeach ?></select></label><button class="button button-ghost" type="submit">Apply</button></form><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">TRANSACTIONS</span><h2><?= count($payments) ?> records</h2></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Participant</th><th>Registration</th><th>Event</th><th>Amount</th><th>Transaction</th><th>Gateway</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr data-testid="payment-row-<?= $payment['id'] ?>"><td><strong><?= esc($payment['participant_name']) ?></strong><span class="table-sub"><?= esc($payment['email']) ?></span></td><td><?= esc($payment['registration_id']) ?></td><td><?= esc($payment['event_name']) ?></td><td><?= esc(money($payment['amount'])) ?></td><td class="mono"><?= esc($payment['txnid']) ?></td><td><?= esc(strtoupper($payment['gateway'])) ?></td><td><span class="<?= status_class($payment['status']) ?>"><?= esc(strtoupper($payment['status'])) ?></span></td><td><?= esc($payment['paid_at']?:$payment['created_at']) ?></td></tr><?php endforeach ?></tbody></table><?php if(!$payments): ?><p class="empty-copy">No payments match these filters.</p><?php endif ?></div></div></section></main>